"use client";
import React, { useEffect, useState } from "react";
import Reviews from "../../about-us/reviews";
import Destinations from "../../after-your-booking/destinations";
import TourCategories from "../tour-categories";

const tabs = [
  { id: "reviews", label: "Reviews" },
  { id: "contactus", label: "Contact us" },
  { id: "destinations", label: "Popular destinations" },
];

const ReviewsPage = () => {
  const [active, setActive] = useState(tabs[0].id);

  useEffect(() => {
    const sections = tabs
      .map((t) => document.getElementById(t.id))
      .filter((el): el is HTMLElement => el !== null);

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) setActive(visible.target.id);
      },
      { rootMargin: "-40% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );

    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, []);

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/reviews.jpg')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.5) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Authentic Reviews
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Over 100 Customer Reviews of TravelShop Booking
            </h1>
            <a
              href="#reviews"
              className="tw-mt-7 tw-inline-flex tw-items-center tw-gap-2 tw-bg-white hover:tw-bg-[#f3f1f7] tw-text-[#854ec9] tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
            >
              See all reviews <span aria-hidden="true">↓</span>
            </a>
          </div>
        </div>
      </section>

      {/* Sticky tab nav */}
      <div className="tw-sticky tw-top-0 tw-z-30 tw-bg-white/90 tw-backdrop-blur tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-4 md:tw-px-8">
          <nav
            className="tw-flex tw-gap-1.5 tw-overflow-x-auto tw-py-3"
            style={{ scrollbarWidth: "none" }}
          >
            {tabs.map((tab) => (
              <a
                key={tab.id}
                href={`#${tab.id}`}
                aria-current={active === tab.id ? "true" : undefined}
                className={`tw-whitespace-nowrap tw-rounded-full tw-px-4 tw-py-2 tw-text-[14px] tw-font-semibold tw-no-underline tw-transition-colors ${
                  active === tab.id
                    ? "tw-bg-[#854ec9] tw-text-white"
                    : "tw-text-[#5d556c] hover:tw-bg-[#faf9fc] hover:tw-text-[#14101c]"
                }`}
              >
                {tab.label}
              </a>
            ))}
          </nav>
        </div>
      </div>

      {/* Reviews intro */}
      <section id="reviews" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            TravelShop Booking Reviews on Trustpilot
          </h2>
          <div className="tw-mt-5 tw-space-y-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            <p className="tw-m-0">
              Welcome to a world where every journey is a new chapter in a
              traveler&apos;s story, where dreams take flight. At TravelShop
              Booking, our core belief is simple yet powerful: &ldquo;Customer
              comes first.&rdquo; This isn&apos;t just a slogan; it defines who
              we are and why we exist.
            </p>
            <p className="tw-m-0">
              But don&apos;t just take our word for it — explore thousands of
              genuine reviews on TravelShop Booking, including honest feedback
              on the services we provide. After every booking, we encourage our
              travelers to share their experiences. These reviews are collected
              through Trustpilot.com, an independent platform that showcases
              unbiased opinions.
            </p>
          </div>
        </div>
      </section>

      {/* Trustpilot reviews (shared) */}
      <Reviews />

      {/* Contact us */}
      <section
        id="contactus"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-text-center">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Get in touch with our Travel Experts
          </h2>
          <a
            href="tel:+905495405402"
            className="tw-mt-4 tw-inline-block tw-text-[22px] tw-font-bold tw-text-[#854ec9] tw-no-underline"
          >
            +90 549 540 54 02
          </a>
          <p className="tw-mt-1 tw-mb-0 tw-text-[14px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#6b6577]">
            24/7 Support
          </p>
          <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            Our team of seasoned tour specialists has explored hundreds of
            countries and brings decades of firsthand travel knowledge. Reach
            out to us now to have all your tour-related questions answered!
          </p>
        </div>
      </section>

      {/* Popular destinations (categories from API) */}
      <TourCategories id="destinations" />

      <Destinations />
    </main>
  );
};

export default ReviewsPage;
